        sc_format_asn1_entry(asn1_com_pubkey_attr + 0, &info->subject.value, &info->subject.len, 0);

        sc_format_asn1_entry(asn1_pubkey_choice + 0, &rsakey_obj, NULL, 0);
        sc_format_asn1_entry(asn1_pubkey_choice + 1, &dsakey_obj, NULL, 0);
